\set ON_ERROR_STOP on
DO $test$ DECLARE before_counts jsonb; after_counts jsonb; h text; r jsonb; BEGIN
SELECT jsonb_build_array((SELECT count(*) FROM public.pos_sales),(SELECT count(*) FROM public.pos_sale_payments),(SELECT count(*) FROM public.pos_cash_movements),(SELECT count(*) FROM public.pos_inventory_movements),(SELECT count(*) FROM public.pos_customer_ledger),(SELECT count(*) FROM public.pos_idempotency_keys),(SELECT count(*) FROM public.pos_financial_operations),(SELECT sum(stock) FROM public.pos_products)) INTO before_counts;
h:=private.financial_operation_hash('sale.cashier_inventory',private.canonical_financial_request_v1('sale.cashier_inventory','{"cash_session_id":"lab-cash-b","sale":{"id":"lab-denial","subtotal":20,"total":20,"payment_method":"cash","amount_paid":20,"balance_due":0,"change_amount":0},"items":[{"id":"lab-race-24-line","product_id":"lab-race-24-product","product_name":"Synthetic race 24","quantity":2,"unit_price":10,"line_subtotal":20,"line_total":20}],"payments":[{"id":"lab-race-24-payment","method":"cash","amount":20,"received_amount":20,"change_amount":0}],"restaurant_settlement":{"parent_order_id":"lab-denial","parent_order_version":"2026-10-01T00:00:00Z"}}'::jsonb),'staff:00000000-0000-0000-0000-0000000000ad','lab-cash-b','lab-station-b');
BEGIN PERFORM public.pos_execute_financial_operation_v1('lab-license-a','lab-device-b','lab-device-token-b','lab-no-pos-session','lab-denied-c',h,'sale.cashier_inventory','{"cash_session_id":"lab-cash-b","sale":{"id":"lab-denial","subtotal":20,"total":20,"payment_method":"cash","amount_paid":20,"balance_due":0,"change_amount":0},"items":[{"id":"lab-race-24-line","product_id":"lab-race-24-product","product_name":"Synthetic race 24","quantity":2,"unit_price":10,"line_subtotal":20,"line_total":20}],"payments":[{"id":"lab-race-24-payment","method":"cash","amount":20,"received_amount":20,"change_amount":0}],"restaurant_settlement":{"parent_order_id":"lab-denial","parent_order_version":"2026-10-01T00:00:00Z"}}'::jsonb); RAISE EXCEPTION 'FAIL_C'; EXCEPTION WHEN SQLSTATE 'P0001' THEN IF SQLERRM NOT LIKE 'POS_PERMISSION_DENIED:%' THEN RAISE; END IF; END;
BEGIN PERFORM public.pos_execute_financial_operation_v1('lab-license-a','lab-device-b','lab-device-token-b','lab-expired-session','lab-denied-d',h,'sale.cashier_inventory','{"cash_session_id":"lab-cash-b","sale":{"id":"lab-denial","subtotal":20,"total":20,"payment_method":"cash","amount_paid":20,"balance_due":0,"change_amount":0},"items":[{"id":"lab-race-24-line","product_id":"lab-race-24-product","product_name":"Synthetic race 24","quantity":2,"unit_price":10,"line_subtotal":20,"line_total":20}],"payments":[{"id":"lab-race-24-payment","method":"cash","amount":20,"received_amount":20,"change_amount":0}],"restaurant_settlement":{"parent_order_id":"lab-denial","parent_order_version":"2026-10-01T00:00:00Z"}}'::jsonb); RAISE EXCEPTION 'FAIL_D'; EXCEPTION WHEN SQLSTATE 'P0001' THEN IF SQLERRM <> 'STAFF_SESSION_EXPIRED' THEN RAISE; END IF; END;
BEGIN PERFORM public.pos_execute_financial_operation_v1('lab-license-a','lab-invalid','lab-device-token-b','lab-staff-session','lab-denied-e',h,'sale.cashier_inventory','{"cash_session_id":"lab-cash-b","sale":{"id":"lab-denial","subtotal":20,"total":20,"payment_method":"cash","amount_paid":20,"balance_due":0,"change_amount":0},"items":[{"id":"lab-race-24-line","product_id":"lab-race-24-product","product_name":"Synthetic race 24","quantity":2,"unit_price":10,"line_subtotal":20,"line_total":20}],"payments":[{"id":"lab-race-24-payment","method":"cash","amount":20,"received_amount":20,"change_amount":0}],"restaurant_settlement":{"parent_order_id":"lab-denial","parent_order_version":"2026-10-01T00:00:00Z"}}'::jsonb); RAISE EXCEPTION 'FAIL_E'; EXCEPTION WHEN SQLSTATE 'P0001' THEN IF SQLERRM <> 'DEVICE_NOT_ALLOWED' THEN RAISE; END IF; END;
BEGIN PERFORM public.pos_execute_financial_operation_v1('lab-license-b','lab-device-c','lab-device-token-c','lab-tenant-b-session','lab-denied-f',h,'sale.cashier_inventory','{"cash_session_id":"lab-cash-b","sale":{"id":"lab-denial","subtotal":20,"total":20,"payment_method":"cash","amount_paid":20,"balance_due":0,"change_amount":0},"items":[{"id":"lab-race-24-line","product_id":"lab-race-24-product","product_name":"Synthetic race 24","quantity":2,"unit_price":10,"line_subtotal":20,"line_total":20}],"payments":[{"id":"lab-race-24-payment","method":"cash","amount":20,"received_amount":20,"change_amount":0}],"restaurant_settlement":{"parent_order_id":"lab-denial","parent_order_version":"2026-10-01T00:00:00Z"}}'::jsonb); RAISE EXCEPTION 'FAIL_F'; EXCEPTION WHEN SQLSTATE 'P0001' THEN IF SQLERRM <> 'RESTAURANT_ORDER_NOT_FOUND' THEN RAISE; END IF; END;
BEGIN PERFORM public.pos_execute_financial_operation_v1('lab-license-a','lab-device-b','lab-device-token-b','lab-staff-session','lab-denied-g',h,'sale.cashier_inventory','{"cash_session_id":"lab-cash-a","sale":{"id":"lab-denial","subtotal":20,"total":20,"payment_method":"cash","amount_paid":20,"balance_due":0,"change_amount":0},"items":[{"id":"lab-race-24-line","product_id":"lab-race-24-product","product_name":"Synthetic race 24","quantity":2,"unit_price":10,"line_subtotal":20,"line_total":20}],"payments":[{"id":"lab-race-24-payment","method":"cash","amount":20,"received_amount":20,"change_amount":0}],"restaurant_settlement":{"parent_order_id":"lab-denial","parent_order_version":"2026-10-01T00:00:00Z"}}'::jsonb); RAISE EXCEPTION 'FAIL_G'; EXCEPTION WHEN SQLSTATE 'P0001' THEN IF SQLERRM <> 'CASH_SESSION_STATION_MISMATCH' THEN RAISE; END IF; END;
SELECT request_hash INTO h FROM public.pos_financial_operations WHERE idempotency_key='lab-race-24-normal' AND license_id='00000000-0000-0000-0000-000000000001';
r:=public.pos_get_financial_operation_receipt('lab-license-a','lab-device-b','lab-device-token-b','lab-staff-session','lab-race-24-normal',h);
IF r->>'status' <> 'NOT_FOUND' THEN RAISE EXCEPTION 'FAIL_H'; END IF;
SELECT jsonb_build_array((SELECT count(*) FROM public.pos_sales),(SELECT count(*) FROM public.pos_sale_payments),(SELECT count(*) FROM public.pos_cash_movements),(SELECT count(*) FROM public.pos_inventory_movements),(SELECT count(*) FROM public.pos_customer_ledger),(SELECT count(*) FROM public.pos_idempotency_keys),(SELECT count(*) FROM public.pos_financial_operations),(SELECT sum(stock) FROM public.pos_products)) INTO after_counts;
IF before_counts IS DISTINCT FROM after_counts THEN RAISE EXCEPTION 'DENIALS_CHANGED_EFFECTS: % -> %',before_counts,after_counts; END IF;
END $test$;
SELECT 'PASS_C11_C_TO_H_WITHOUT_EFFECTS' result;